// probe: compile-only
io :: import "std/io"

main :: fn() {
    x := 5
    k := 1
    match k {
        case 1: {
            x = 0
            fall
        }
        case 2: { fall }
        case 3: {
            io.println("{}", 10 / x)
        }
        else: {
            io.println("other")
        }
    }
}

